          out.push({
            rule: rule.id,
            severity: rule.severity,
            file: wf,
            line: text.slice(0, m.index).split('\n').length,
            what: `the deploy substitutes into ${target}, which does not exist`,
            why: rule.why,
            fix: `point the sed at the file that carries "${pattern}", or drop the substitution`,
            doc: rule.doc,
